(self.webpackChunkcapstone_stunting_app=self.webpackChunkcapstone_stunting_app||[]).push([[16],{652:()=>{document.addEventListener("DOMContentLoaded",(function(){const a=document.querySelector(".navbar");let n=0;window.addEventListener("scroll",(()=>{const i=window.pageYOffset;if(i<=0)a.classList.remove("nav-scrolled-down"),a.classList.add("nav-scrolled-up");else if(i>n){a.classList.remove("nav-scrolled-up"),a.classList.add("nav-scrolled-down");const n=document.getElementById("nav-menu");n&&n.classList.contains("active")&&n.classList.remove("active")}else a.classList.remove("nav-scrolled-down"),a.classList.add("nav-scrolled-up");n=i}))}))},973:()=>{class a{constructor(){this.responses={normalHeightNormalWeight:{title:"Pertumbuhan Normal",interpretation:["**Status Stunting: Normal**: Tinggi badan anak Anda sesuai dengan usianya.","**Berat Badan: Normal**: Berat badan anak Anda berada dalam rentang sehat untuk usianya."],conclusion:"Anak Anda memiliki pertumbuhan yang optimal, dengan tinggi dan berat badan yang sesuai dengan usianya.",recommendations:["**Pertahankan Pola Makan Seimbang**: Teruskan memberi anak makanan bergizi seimbang yang mencakup protein, karbohidrat kompleks, lemak sehat, serta buah dan sayuran.","**Aktivitas Fisik Teratur**: Dorong anak untuk tetap aktif sesuai usianya melalui bermain dan bergerak.","**Pemeriksaan Rutin**: Tetap lakukan pemeriksaan tumbuh kembang secara berkala dengan tenaga kesehatan.","**Stimulasi Perkembangan**: Berikan stimulasi yang sesuai dengan tahap perkembangannya untuk mendukung pertumbuhan optimal."]},normalHeightOverweight:{title:"Normal dengan Kelebihan Berat Badan",interpretation:["**Status Stunting: Normal**: Tinggi badan anak Anda sesuai dengan usianya.","**Berat Badan: Berlebih**: Berat badan anak Anda berada di atas rentang normal untuk usianya."],conclusion:"Meskipun status stunting anak Anda normal, berat badannya lebih tinggi dibandingkan anak seusianya. Ini perlu perhatian khusus.",recommendations:["**Konsultasi dengan Ahli Gizi atau Dokter**: Dapatkan saran profesional untuk manajemen berat badan yang aman untuk anak.","**Evaluasi Pola Makan**: Periksa ukuran porsi dan jenis makanan yang dikonsumsi anak.","**Batasi Makanan Olahan**: Kurangi konsumsi makanan tinggi gula, lemak jenuh, dan makanan olahan.","**Tingkatkan Aktivitas Fisik**: Dorong anak untuk lebih aktif bergerak setiap hari dengan aktivitas yang menyenangkan.","**Tetap Berikan Nutrisi Seimbang**: Jangan batasi makanan secara drastis, pastikan semua nutrisi penting tetap terpenuhi."]},normalHeightUnderweight:{title:"Normal dengan Berat Badan Kurang",interpretation:["**Status Stunting: Normal**: Tinggi badan anak Anda sesuai dengan usianya.","**Berat Badan: Kurang**: Berat badan anak Anda berada di bawah rentang normal untuk usianya."],conclusion:"Meskipun tinggi anak Anda normal, berat badannya perlu ditingkatkan untuk mencapai pertumbuhan optimal.",recommendations:["**Tingkatkan Asupan Kalori**: Berikan makanan padat nutrisi dan tinggi kalori seperti alpukat, ikan, kacang-kacangan, dan produk susu penuh.","**Makan Lebih Sering**: Tawarkan makanan utama dan camilan sehat lebih sering dalam porsi yang tidak terlalu besar.","**Konsultasi Medis**: Kunjungi dokter untuk memastikan tidak ada masalah kesehatan yang mendasari.","**Pantau Perkembangan**: Timbang berat anak secara teratur untuk memastikan ada kemajuan.","**Hindari Junk Food**: Meskipun perlu meningkatkan kalori, tetap hindari makanan tidak sehat."]},mildStuntingNormalWeight:{title:"Stunting Ringan dengan Berat Normal",interpretation:["**Status Stunting: Ringan**: Tinggi badan anak Anda sedikit di bawah standar untuk usianya.","**Berat Badan: Normal**: Berat badan anak Anda berada dalam rentang normal untuk usianya."],conclusion:"Anak Anda menunjukkan tanda stunting ringan, yang berarti tinggi badannya sedikit di bawah standar untuk usianya, meskipun berat badannya normal.",recommendations:["**Fokus pada Nutrisi Penunjang Pertumbuhan**: Berikan makanan kaya protein, kalsium, zinc, dan vitamin A dan D.","**Konsumsi Protein Berkualitas**: Pastikan anak mendapatkan protein berkualitas dari telur, daging tanpa lemak, ikan, dan kacang-kacangan.","**Suplementasi Jika Diperlukan**: Konsultasikan dengan dokter tentang kemungkinan suplementasi nutrisi.","**Konsultasi dengan Ahli Gizi**: Dapatkan saran spesifik untuk meningkatkan pertumbuhan anak.","**Perhatikan Higiene dan Sanitasi**: Cegah infeksi yang dapat menghambat pertumbuhan."]},severeStuntingNormalWeight:{title:"Stunting Berat - Perhatian Khusus Diperlukan",interpretation:["**Status Stunting: Berat**: Tinggi badan anak Anda jauh di bawah standar untuk usianya.","**Berat Badan: Normal**: Berat badan anak Anda berada dalam rentang normal untuk usianya."],conclusion:"Anak Anda mengalami stunting berat, meskipun berat badannya normal untuk usianya. Ini memerlukan perhatian khusus.",recommendations:["**Konsultasi Medis Segera**: Temui dokter anak untuk evaluasi menyeluruh dan rencana penanganan.","**Program Nutrisi Intensif**: Ikuti program nutrisi khusus yang dirancang oleh ahli gizi.","**Suplementasi Gizi**: Mungkin diperlukan suplementasi vitamin, mineral, atau formula khusus.","**Pemantauan Rutin**: Lakukan pemeriksaan tumbuh kembang secara teratur.","**Periksa Kondisi Medis Lain**: Stunting berat dapat terkait dengan kondisi medis tertentu yang perlu ditangani.","**Dukungan Holistik**: Perhatikan juga aspek stimulasi, kesehatan lingkungan, dan dukungan psikososial."]},severeStuntingWithUnderweight:{title:"Stunting Berat dengan Berat Badan Kurang",interpretation:["**Status Stunting: Berat**: Tinggi badan anak Anda jauh di bawah standar untuk usianya.","**Berat Badan: Kurang**: Berat badan anak Anda juga berada di bawah standar untuk usianya."],conclusion:"Anak Anda mengalami stunting berat disertai dengan berat badan kurang. Kombinasi ini membutuhkan intervensi segera dan komprehensif.",recommendations:["**Konsultasi Medis Segera**: Temui dokter anak untuk evaluasi menyeluruh dan penanganan intensif.","**Program Nutrisi Prioritas**: Ikuti program nutrisi khusus yang dirancang oleh ahli gizi untuk mengatasi stunting dan berat badan kurang secara bersamaan.","**Makanan Padat Gizi**: Berikan makanan dengan densitas nutrisi tinggi seperti telur, ikan, daging tanpa lemak, kacang-kacangan, dan susu.","**Pola Makan Teratur**: Berikan 5-6 kali makan sehari (3 makanan utama + 2-3 camilan bergizi) untuk meningkatkan asupan kalori dan nutrisi.","**Suplementasi Gizi**: Konsultasikan dengan dokter untuk suplementasi vitamin A, D, zink, zat besi dan kalsium sesuai kebutuhan.","**Pencegahan Infeksi**: Pastikan kebersihan dan vaksinasi lengkap untuk mencegah infeksi yang dapat memperburuk kondisi.","**Pemantauan Ketat**: Lakukan pemeriksaan tumbuh kembang secara teratur, idealnya setiap 2 minggu di awal intervensi."]},obesity:{title:"Obesitas - Perhatian Khusus Diperlukan",interpretation:["**Status Berat: Obesitas**: Berat badan anak Anda jauh di atas normal untuk usianya.","**Kondisi Ini Memerlukan Perhatian**: Obesitas pada anak dapat menyebabkan masalah kesehatan jangka panjang."],conclusion:"Anak Anda mengalami obesitas, yang perlu ditangani secara hati-hati dengan pendekatan komprehensif untuk mencapai berat badan yang lebih sehat.",recommendations:["**Konsultasi dengan Dokter Anak**: Dapatkan evaluasi menyeluruh dan panduan pengelolaan berat badan yang aman.","**Perubahan Pola Makan Bertahap**: Fokus pada makanan bergizi, porsi yang tepat, dan mengurangi makanan olahan dan tinggi gula.","**Aktivitas Fisik Teratur**: Tingkatkan aktivitas fisik secara bertahap melalui kegiatan yang menyenangkan.","**Pendekatan Keluarga**: Libatkan seluruh keluarga dalam menerapkan gaya hidup sehat.","**Hindari Diet Ketat**: Fokus pada pertumbuhan sehat, bukan penurunan berat badan drastis.","**Dukungan Psikologis**: Perhatikan aspek psikologis dan citra diri anak."]}},this.generalInfo={whatIsStunting:{title:"Apa itu Stunting?",content:["**Stunting adalah** kondisi gagal tumbuh pada anak akibat kekurangan gizi kronis, terutama pada 1.000 hari pertama kehidupan (sejak janin hingga anak berusia 2 tahun).","**Secara teknis**, stunting didefinisikan sebagai kondisi dimana tinggi badan anak berada di bawah -2 standar deviasi dari median tinggi badan menurut usia berdasarkan standar WHO.","**Dampak stunting** tidak hanya pada fisik anak (tinggi badan yang rendah), tetapi juga pada perkembangan otak, yang dapat mempengaruhi kemampuan kognitif dan prestasi akademik di masa depan."]},stuntingCauses:{title:"Penyebab Stunting",content:["**Kekurangan gizi kronis** selama masa kehamilan dan awal kehidupan anak.","**Infeksi berulang** seperti diare, cacingan, dan infeksi saluran pernapasan yang mengganggu penyerapan nutrisi.","**Praktik pemberian makan yang buruk**, termasuk ASI eksklusif yang kurang, MPASI yang tidak adekuat, dan keragaman makanan yang rendah.","**Sanitasi dan kebersihan yang buruk** meningkatkan risiko infeksi dan penyakit.","**Faktor sosial ekonomi** seperti kemiskinan dan akses terbatas ke layanan kesehatan.","**Faktor maternal** termasuk status gizi ibu sebelum dan selama kehamilan, serta kesehatan ibu secara umum."]},stuntingPrevention:{title:"Pencegahan Stunting",content:["**Nutrisi optimal ibu** sebelum dan selama kehamilan serta saat menyusui.","**ASI eksklusif selama 6 bulan pertama** dilanjutkan dengan MPASI yang adekuat hingga usia 2 tahun atau lebih.","**Makanan Pendamping ASI (MPASI)** yang tepat waktu, adekuat, aman, dan berkualitas mulai usia 6 bulan.","**Pemantauan pertumbuhan rutin** untuk deteksi dini masalah pertumbuhan.","**Pola asuh yang responsif** dan stimulasi yang baik untuk perkembangan anak.","**Praktik sanitasi dan kebersihan yang baik** termasuk mencuci tangan, air bersih, dan sanitasi layak.","**Imunisasi lengkap** dan pencegahan serta penanganan penyakit yang tepat."]},vitaminsForStunting:{title:"Vitamin dan Suplemen untuk Mencegah Stunting",content:["**Vitamin A**: Penting untuk kesehatan mata, pertumbuhan tulang, dan sistem kekebalan tubuh. Sumber: wortel, bayam, pepaya, mangga, hati, dan telur.","**Vitamin D**: Membantu penyerapan kalsium dan fosfor untuk pertumbuhan tulang. Sumber: sinar matahari pagi, ikan berlemak, kuning telur, dan produk susu yang difortifikasi.","**Vitamin B Kompleks**: Mendukung metabolisme dan pertumbuhan sel. Sumber: daging tanpa lemak, kacang-kacangan, biji-bijian utuh, dan sayuran hijau.","**Asam Folat**: Penting untuk pembentukan sel baru. Sumber: sayuran hijau, kacang-kacangan, biji-bijian utuh, dan buah jeruk.","**Kalsium**: Sangat penting untuk pembentukan tulang dan gigi. Sumber: susu, keju, yogurt, ikan teri, dan sayuran hijau gelap.","**Zat Besi**: Mencegah anemia yang dapat menghambat pertumbuhan. Sumber: daging merah, hati, kacang-kacangan, bayam, dan makanan yang difortifikasi.","**Zinc**: Penting untuk pertumbuhan dan sistem kekebalan tubuh. Sumber: daging, makanan laut, kacang-kacangan, dan biji-bijian utuh.","**Protein**: Blok bangunan penting untuk pertumbuhan dan perbaikan jaringan. Sumber: telur, daging, ikan, susu, kedelai, dan kacang-kacangan."]},exerciseForChildren:{title:"Aktivitas Fisik untuk Mendukung Pertumbuhan Optimal",content:["**Untuk Bayi (0-1 tahun)**:","• **Tummy Time**: Letakkan bayi tengkurap saat terjaga untuk memperkuat leher dan bahu","• **Gerakan Bebas**: Berikan waktu bagi bayi untuk bergerak bebas di lantai yang aman","• **Aktivitas Air**: Pengenalan ke air dalam suhu yang tepat dapat membantu perkembangan motorik","**Untuk Balita (1-3 tahun)**:","• **Berjalan dan Berlari**: Dorong anak untuk aktif bergerak di taman bermain","• **Permainan Lempar Bola**: Membantu koordinasi dan kekuatan otot","• **Menari**: Aktivitas menyenangkan yang melatih keseimbangan dan koordinasi","**Untuk Anak Prasekolah (3-5 tahun)**:","• **Bersepeda dengan Roda Bantuan**: Membangun kekuatan kaki dan keseimbangan","• **Berenang**: Olahraga yang baik untuk seluruh tubuh","• **Permainan Aktif**: Seperti kejar-kejaran, lompat tali, atau bermain bola"]},nutritionalPrograms:{title:"Program Nutrisi untuk Pencegahan Stunting",content:["**Program 1000 Hari Pertama Kehidupan**:","• Fokus pada nutrisi ibu hamil dan menyusui","• Pemantauan pertumbuhan bayi secara teratur","• Edukasi tentang MPASI yang tepat","**Pemberian Makanan Tambahan (PMT)**:","• PMT untuk ibu hamil dan menyusui Kurang Energi Kronis (KEK)","• PMT untuk balita kekurangan gizi","• Biskuit atau makanan padat gizi lainnya","**Suplementasi Gizi Mikro**:","• Tablet tambah darah untuk ibu hamil","• Kapsul vitamin A untuk balita","• Taburia (sprinkle) yang mengandung berbagai mikronutrien","**Program Air Bersih dan Sanitasi (WASH)**:","• Akses terhadap air bersih","• Sanitasi yang layak","• Praktik kebersihan seperti cuci tangan pakai sabun"]}},this.generalResponses={vitamin:{title:"Vitamin dan Suplemen untuk Pencegahan Stunting",content:"Untuk mendukung pencegahan stunting dan kesehatan optimal, berikut beberapa vitamin dan suplemen yang direkomendasikan:\n\n1. Vitamin A: \n   • Penting untuk pertumbuhan, perkembangan, dan fungsi kekebalan tubuh\n   • Sumber: wortel, ubi jalar, bayam, telur, susu\n\n2. Vitamin D: \n   • Membantu penyerapan kalsium dan penting untuk pertumbuhan tulang\n   • Sumber: sinar matahari, ikan berlemak, kuning telur, susu yang difortifikasi\n\n3. Kalsium: \n   • Penting untuk pembentukan tulang dan gigi yang kuat\n   • Sumber: susu, keju, yogurt, ikan teri, tahu yang diolah dengan kalsium\n\n4. Zinc: \n   • Mendukung pertumbuhan dan sistem kekebalan tubuh\n   • Sumber: daging merah, unggas, kacang-kacangan, biji-bijian\n\n5. Zat Besi: \n   • Mencegah anemia dan mendukung perkembangan otak\n   • Sumber: daging merah, hati, bayam, kacang-kacangan\n\n6. Asam Folat: \n   • Sangat penting untuk pertumbuhan sel dan perkembangan jaringan\n   • Sumber: sayuran hijau, kacang-kacangan, buah jeruk\n\nNamun, sebaiknya konsumsi suplemen dilakukan setelah berkonsultasi dengan dokter atau ahli gizi untuk mendapatkan dosis yang tepat sesuai kebutuhan individu."},nutrition:{title:"Pola Makan Seimbang untuk Mencegah Stunting",content:"Pola makan seimbang untuk mencegah stunting dan mendukung pertumbuhan optimal:\n\n1. Protein Berkualitas:\n   • Telur, ikan, daging tanpa lemak, tahu, tempe\n   • Penting untuk pertumbuhan dan pembentukan otot\n\n2. Karbohidrat Kompleks:\n   • Nasi merah, roti gandum, ubi, kentang\n   • Sumber energi yang stabil\n\n3. Lemak Sehat:\n   • Alpukat, kacang-kacangan, minyak zaitun\n   • Penting untuk perkembangan otak\n\n4. Sayuran dan Buah-buahan:\n   • Minimal 5 porsi sehari dengan beragam warna\n   • Sumber vitamin, mineral dan antioksidan\n\n5. Susu dan Produk Susu:\n   • Sumber kalsium untuk pertumbuhan tulang\n   • 2-3 porsi sehari\n\nMakan dengan teratur 3 kali sehari plus 2 camilan sehat dan hindari makanan olahan tinggi gula, garam dan lemak trans."},growth:{title:"Faktor yang Mempengaruhi Pertumbuhan",content:"Pertumbuhan tinggi badan anak dipengaruhi oleh berbagai faktor:\n\n1. Genetik/keturunan: Memengaruhi sekitar 60-80% potensi tinggi badan\n\n2. Nutrisi: Asupan protein, kalsium, vitamin D, dan zinc sangat penting untuk pertumbuhan optimal\n\n3. Hormon pertumbuhan: Diproduksi oleh kelenjar pituitari, sangat aktif saat tidur\n\n4. Aktivitas fisik: Merangsang produksi hormon pertumbuhan dan memperkuat tulang\n\n5. Kualitas tidur: Waktu tidur yang cukup meningkatkan produksi hormon pertumbuhan\n\n6. Kesehatan umum: Infeksi kronis atau penyakit dapat menghambat pertumbuhan\n\nTips meningkatkan pertumbuhan:\n• Pastikan anak mendapat nutrisi seimbang\n• Dorong aktivitas fisik teratur\n• Jaga kualitas tidur (10-12 jam untuk anak kecil)\n• Periksa kesehatan secara berkala\n• Hindari stres berlebihan yang dapat memengaruhi pertumbuhan"},activity:{title:"Aktivitas Fisik untuk Mendukung Pertumbuhan",content:"Aktivitas fisik yang direkomendasikan untuk mendukung pertumbuhan optimal anak:\n\nUntuk bayi (0-12 bulan):\n• Waktu tengkurap dengan pengawasan\n• Permainan interaktif yang menggerakkan tangan dan kaki\n• Stimulasi sensori dengan mainan berwarna-warni dan bertekstur\n\nUntuk batita (1-3 tahun):\n• Aktivitas aktif minimal 180 menit sehari\n• Bermain di luar ruangan: berlari, melompat, melempar bola\n• Aktivitas yang melatih keseimbangan, seperti berjalan di atas garis\n\nUntuk anak prasekolah (3-5 tahun):\n• Aktivitas aktif 180 menit sehari, termasuk 60 menit aktivitas energik\n• Bermain di taman bermain: panjat, ayunan, seluncuran\n• Permainan kelompok sederhana seperti kejar-kejaran\n• Aktivitas yang mengembangkan koordinasi seperti menendang/melempar bola\n\nTips penerapan:\n• Jadikan aktivitas fisik menyenangkan, bukan kewajiban\n• Batasi waktu di depan layar (TV, gadget)\n• Jadi teladan dengan aktif bersama anak\n• Sesuaikan aktivitas dengan minat dan kemampuan anak\n• Berikan pujian untuk upaya, bukan hanya hasil"},greeting:{title:"Selamat Datang di Stuntify Bot",content:"Halo! Saya Stuntify Bot, asisten kesehatan yang siap membantu Anda dengan informasi seputar:\n• Stunting dan pencegahannya\n• Pertumbuhan anak yang optimal\n• Rekomendasi nutrisi dan vitamin\n• Pola makan sehat untuk anak\n• Aktivitas fisik untuk mendukung pertumbuhan\n• Tips pemantauan pertumbuhan anak\n\nApa yang ingin Anda ketahui tentang kesehatan dan pencegahan stunting pada anak hari ini?"},default:{title:"Bantuan Stuntify Bot",content:"Terima kasih atas pertanyaan Anda. Untuk memberikan informasi yang akurat, saya perlu memahami pertanyaan Anda dengan lebih jelas.\n\nAnda bisa bertanya tentang:\n• Apa itu stunting dan bagaimana mencegahnya\n• Faktor-faktor yang memengaruhi pertumbuhan anak\n• Rekomendasi vitamin dan nutrisi untuk anak\n• Pola makan sehat untuk mencegah stunting\n• Aktivitas fisik yang mendukung pertumbuhan\n• Cara memantau pertumbuhan anak secara efektif\n\nSilakan ajukan pertanyaan Anda kembali dengan lebih spesifik."},stunting:{title:"Apa itu Stunting?",content:"Stunting adalah kondisi gagal tumbuh pada anak akibat kekurangan gizi kronis, terutama dalam 1000 hari pertama kehidupan (dari kehamilan hingga usia 2 tahun).\n\nPenyebab utama stunting:\n• Kekurangan nutrisi selama kehamilan\n• Pemberian ASI yang tidak optimal\n• Makanan pendamping ASI yang tidak adekuat\n• Infeksi berulang dan penyakit kronis\n• Sanitasi dan kebersihan yang buruk\n\nDampak stunting:\n• Penurunan perkembangan kognitif dan kecerdasan\n• Penurunan produktivitas\n• Peningkatan risiko penyakit tidak menular di masa dewasa\n• Dampak ekonomi jangka panjang\n\nPencegahan stunting harus dimulai sejak masa kehamilan dengan memastikan ibu mendapat nutrisi yang cukup, pemberian ASI eksklusif selama 6 bulan pertama, pemberian MPASI yang tepat, serta menjaga kebersihan dan sanitasi lingkungan."}}}getResponseForChild(a){const{stunting_status:n,weight_status:i,height:e,age:t,gender:u,weight:s,name:r,ml_stunting_result:k,ml_wasting_result:g}=a;let m;return m="Normal"===n?i&&i.includes("Normal")?this.responses.normalHeightNormalWeight:i&&(i.includes("Lebih")||i.includes("Obesitas"))?this.responses.normalHeightOverweight:this.responses.normalHeightUnderweight:"Stunting Ringan"===n?this.responses.mildStuntingNormalWeight:"Stunting Berat"===n&&i&&i.includes("Kurang")?this.responses.severeStuntingWithUnderweight:this.responses.severeStunting,"Obesitas"===i&&(m=this.responses.obesity),this.formatResponseDetailed(m,a)}formatSupplementsSection(a){if(!a||0===a.length)return"";let n="**Rekomendasi Vitamin & Suplemen:**\n\n";return a.slice(0,3).forEach(((a,i)=>{n+=`${i+1}. **${a.name}**\n`,n+=`   • Manfaat: ${a.benefits}\n`,n+=`   • Sumber: ${a.sources}\n\n`})),n+="**Catatan:** Konsultasikan dengan dokter atau ahli gizi sebelum memberikan suplemen tambahan.",n}formatResponse(a,n){const{title:i,interpretation:e,conclusion:t,recommendations:u}=a,{height:s,age:r,gender:k,weight:g,stunting_status:m,weight_status:d}=n,l=this.getMinNormalHeight(r,k),o=this.getIdealWeight(r,k);let p=`**${i}**\n\n`;p+="**Interpretasi Data:**\n\n";for(let a of e)p+=`• ${a}\n\n`;p+=`• **Tinggi Badan**: ${s} cm (Usia ${r} bulan, ${k}): `,p+="Normal"===m?`Tinggi badan ini berada dalam rentang normal untuk anak ${k.toLowerCase()} usia ${r} bulan.\n\n`:"Stunting Ringan"===m?`Tinggi badan ini sedikit di bawah standar untuk anak ${k.toLowerCase()} usia ${r} bulan (minimal normal sekitar ${l} cm).\n\n`:`Tinggi badan ini jauh di bawah standar untuk anak ${k.toLowerCase()} usia ${r} bulan (minimal normal sekitar ${l} cm).\n\n`,g&&(p+=`• **Berat Badan**: ${g} kg (Usia ${r} bulan, ${k}): `,d.includes("Normal")?p+="Berat badan ini berada dalam rentang normal untuk anak seusianya.\n\n":d.includes("Lebih")||d.includes("Obesitas")?p+=`Berat badan ini di atas rata-rata untuk anak seusianya (ideal sekitar ${o} kg).\n\n`:p+=`Berat badan ini di bawah rata-rata untuk anak seusianya (ideal sekitar ${o} kg).\n\n`),p+=`**Kesimpulan:**\n\n${t}\n\n`,p+="**Rekomendasi:**\n\n";for(let a=0;a<u.length;a++)p+=`${a+1}. ${u[a]}\n\n`;return p+="**Peringatan:**\n\n",p+="• Informasi ini bersifat umum dan tidak menggantikan konsultasi medis langsung.\n\n",p+="• Selalu konsultasikan dengan dokter atau ahli gizi untuk penanganan yang tepat.",p}formatResponseDetailed(a,n){const{title:i,interpretation:e,conclusion:t,recommendations:u}=a,{height:s,age:r,gender:k,weight:g,stunting_status:m,weight_status:d,name:l}=n,o=l||"Anak Anda";let p=`Halo, orangtua dari ${o}! \n\nBerdasarkan hasil pengukuran, ${o} (${r} bulan / ${(r/12).toFixed(1)} tahun) memiliki kondisi: **${i}**\n\n**Interpretasi Kondisi:**\n${e.join("\n")}\n\n**Kesimpulan:**\n${t}\n\n**Rekomendasi Tindakan:**\n`;return u.forEach(((a,n)=>{p+=`${n+1}. ${a}\n`})),p+="\n**Catatan Penting:**\n• Informasi ini bersifat umum dan tidak menggantikan konsultasi medis langsung\n• Selalu konsultasikan dengan dokter atau ahli gizi untuk penanganan yang tepat\n• Pantau pertumbuhan anak secara berkala",p}getGeneralResponse(a){const n=a.toLowerCase();return n.includes("vitamin")||n.includes("suplemen")?this.generalResponses.vitamin.content:n.includes("makan")||n.includes("nutrisi")||n.includes("makanan")?this.generalResponses.nutrition.content:n.includes("stunting")?this.generalResponses.stunting.content:n.includes("pertumbuhan")||n.includes("tinggi badan")?this.generalResponses.growth.content:n.includes("aktivitas")||n.includes("bermain")||n.includes("olahraga")?this.generalResponses.activity.content:n.includes("terima kasih")||n.includes("makasih")?"Sama-sama! Senang bisa membantu Anda. Jika ada pertanyaan lain seputar kesehatan, nutrisi, atau pencegahan stunting, jangan ragu untuk bertanya kembali.":n.includes("halo")||n.includes("hai")||n.includes("hi")?this.generalResponses.greeting.content:this.generalResponses.default.content}generateInitialRecommendation(a,n,i,e,t,u,s,r){(i/12).toFixed(1);const k=e-n,g={stuntingBeratWithUnderweight:()=>`Halo, orangtua dari ${t}! \n\nBerdasarkan hasil pengukuran, ${t} memiliki kondisi stunting berat dengan tinggi ${n} cm (sekitar ${k.toFixed(1)} cm di bawah standar normal) dan juga berat badan kurang yaitu ${s} kg.\n\nKondisi ini memerlukan perhatian medis segera karena kombinasi stunting berat dan berat badan kurang (yang disebut stunting dan wasting) membutuhkan penanganan komprehensif:\n\n1. Evaluasi Kondisi:\n   • Stunting berat menunjukkan adanya kekurangan gizi kronis jangka panjang\n   • Segera konsultasikan ke dokter anak atau ahli gizi untuk evaluasi menyeluruh\n   • Pemeriksaan darah mungkin diperlukan untuk mengidentifikasi kekurangan nutrisi spesifik\n\n2. Rekomendasi Nutrisi:\n   • Prioritaskan makanan padat nutrisi: telur, ikan, daging, susu, kacang-kacangan\n   • Berikan makanan dengan densitas kalori tinggi: tambahkan minyak zaitun atau alpukat ke makanan\n   • Suplementasi vitamin A, D, zink, dan zat besi sesuai anjuran dokter\n\n3. Pola Makan:\n   • Berikan 5-6 kali makan sehari (3 makanan utama + 2-3 snack bergizi)\n   • Pastikan setiap makanan mengandung protein, karbohidrat kompleks dan lemak sehat\n   • Hindari makanan "pengisi perut" seperti snack manis atau minuman manis\n\n4. Aktivitas Fisik:\n   • Dorong aktivitas yang menyenangkan seperti bermain di luar rumah\n   • Fokus pada aktivitas yang membangun kekuatan otot secara bertahap\n   • Pastikan istirahat dan tidur yang cukup (10-12 jam untuk balita)\n\n5. Tips untuk Orangtua:\n   • Pantau pertumbuhan secara teratur (setiap bulan) dengan kurva pertumbuhan WHO\n   • Pertimbangkan program intervensi stunting dari puskesmas atau klinik gizi\n   • Perhatikan kebersihan dan pencegahan infeksi yang bisa menghambat pertumbuhan\n\nPenting untuk memahami bahwa perbaikan stunting memerlukan waktu dan konsistensi. Dengan penanganan yang tepat dan dini, masih ada kesempatan untuk mengejar ketertinggalan pertumbuhan, terutama jika anak masih di bawah 2 tahun (periode 1000 hari pertama kehidupan).`,stuntingBerat:()=>`Halo, orangtua dari ${t}! \n\nBerdasarkan hasil pengukuran, ${t} berada dalam kategori stunting berat dengan tinggi ${n} cm (sekitar ${k.toFixed(1)} cm di bawah standar normal untuk usianya).\n\nIni memerlukan perhatian khusus, namun jangan khawatir, masih banyak yang bisa dilakukan:\n\n1. Evaluasi Kondisi:\n   • Stunting berat menunjukkan kekurangan gizi kronis jangka panjang\n   • Segera konsultasikan ke dokter anak untuk evaluasi menyeluruh\n   • Pemeriksaan lebih lanjut mungkin diperlukan untuk mengetahui penyebab\n\n2. Rekomendasi Nutrisi:\n   • Prioritaskan makanan tinggi protein: telur, ikan, daging, susu, kacang-kacangan\n   • Pastikan asupan kalsium dan vitamin D mencukupi untuk pertumbuhan tulang\n   • Konsultasikan dengan dokter tentang suplementasi vitamin dan mineral\n\n3. Pola Makan:\n   • Berikan makanan dengan nutrisi tinggi dalam porsi kecil tapi sering\n   • Pastikan setiap makanan mengandung protein dan kalsium\n   • Tambahkan lemak sehat seperti minyak zaitun atau alpukat untuk meningkatkan kalori\n   • Hindari junk food dan makanan rendah nutrisi\n\n4. Aktivitas Fisik:\n   • Dorong aktivitas fisik yang menyenangkan dan sesuai kemampuan\n   • Latihan yang melibatkan berat badan dapat menstimulasi pertumbuhan tulang\n   • Pastikan istirahat dan tidur yang cukup (10-12 jam per hari)\n\n5. Tips untuk Orangtua:\n   • Pantau pertumbuhan secara teratur setiap bulan\n   • Cari dukungan dari program pemerintah untuk pencegahan stunting\n   • Hindari infeksi berulang dengan menjaga kebersihan\n\nIngat bahwa perbaikan kondisi stunting memerlukan waktu dan konsistensi. Terutama jika anak masih di bawah 2 tahun, potensi untuk mengejar pertumbuhan optimal masih terbuka lebar.`,stuntingRinganWithUnderweight:()=>`Halo, orangtua dari ${t}! \n\nHasil pengukuran menunjukkan bahwa ${t} mengalami stunting ringan dengan tinggi ${n} cm (sekitar ${k.toFixed(1)} cm di bawah standar normal) dan juga berat badan kurang yaitu ${s} kg.\n\nKondisi ini memerlukan perhatian lebih untuk mendukung pertumbuhan yang optimal:\n\n1. Evaluasi Kondisi:\n   • Kombinasi stunting ringan dan berat badan kurang menunjukkan adanya kekurangan gizi\n   • Pantau pertumbuhan setiap 2 minggu hingga kondisi membaik\n   • Konsultasikan dengan dokter anak untuk evaluasi lengkap\n\n2. Rekomendasi Nutrisi:\n   • Perbanyak asupan protein: telur, ikan, daging, produk susu, kacang-kacangan\n   • Berikan makanan padat energi seperti kentang, pasta, sereal utuh\n   • Tambahkan sumber lemak sehat seperti alpukat, minyak zaitun, kacang-kacangan\n   • Suplementasi vitamin A, D, dan mineral (zinc, zat besi) setelah konsultasi dengan dokter\n\n3. Pola Makan:\n   • Berikan makanan kecil tapi sering (5-6 kali sehari)\n   • Setiap makanan utama harus mengandung protein, karbohidrat kompleks dan lemak sehat\n   • Buatlah makanan menarik dan bervariasi untuk meningkatkan nafsu makan\n   • Hindari minuman manis yang mengenyangkan tanpa memberikan nutrisi\n\n4. Aktivitas Fisik:\n   • Dorong aktivitas fisik ringan tetapi teratur\n   • Batasi aktivitas berlebihan yang membakar kalori terlalu banyak\n   • Pastikan tidur yang cukup untuk produksi hormon pertumbuhan\n\n5. Tips untuk Orangtua:\n   • Catat asupan makanan untuk mengidentifikasi pola makan yang perlu diperbaiki\n   • Pantau berat dan tinggi badan setiap 2 minggu\n   • Periksa adanya infeksi atau masalah kesehatan lain yang mempengaruhi nafsu makan\n   • Pertimbangkan konsultasi dengan ahli gizi untuk rencana nutrisi khusus\n\nDengan penanganan yang tepat, stunting ringan dan berat badan kurang masih dapat diperbaiki dengan baik, terutama jika anak masih dalam periode emas pertumbuhan (di bawah 2 tahun). Tetap konsisten dan pantau kemajuannya secara teratur.`,stuntingRingan:()=>`Halo, orangtua dari ${t}! \n\nHasil pengukuran menunjukkan bahwa ${t} mengalami stunting ringan dengan tinggi ${n} cm (sekitar ${k.toFixed(1)} cm di bawah standar normal untuk usianya).\n\nStunting ringan masih bisa diatasi dengan intervensi yang tepat. Berikut rekomendasinya:\n\n1. Evaluasi Kondisi:\n   • Stunting ringan mengindikasikan adanya keterlambatan pertumbuhan yang masih bisa dikejar\n   • Lakukan pemantauan pertumbuhan rutin setiap bulan\n   • Diskusikan dengan dokter anak untuk mendapatkan saran yang lebih personal\n\n2. Rekomendasi Nutrisi & Vitamin:\n   • Vitamin A, D dan mineral seperti kalsium, zinc dan zat besi\n   • Protein berkualitas tinggi dari daging, unggas, ikan, telur, dan susu\n   • Asam lemak esensial untuk perkembangan otak (dari ikan berlemak, alpukat)\n\n3. Pola Makan Ideal:\n   • Sajikan makanan dengan prinsip "isi piringku" (1/2 sayur dan buah, 1/4 protein, 1/4 karbohidrat)\n   • Batasi makanan dan minuman tinggi gula, garam, dan lemak jenuh\n   • Berikan air putih sebagai minuman utama\n   • Jadwalkan waktu makan teratur 3x sehari dengan 2x camilan sehat\n\n4. Aktivitas Fisik yang Disarankan:\n   • Mendorong aktivitas fisik minimal 60-180 menit sehari sesuai usia\n   • Aktivitas yang menyenangkan seperti berlari, bermain bola, berenang, atau bersepeda\n   • Batasi waktu di depan layar (TV, tablet, smartphone)\n   • Pastikan tidur yang cukup (10-12 jam untuk balita, 9-10 jam untuk anak-anak)\n\n5. Tips Pemantauan:\n   • Dokumentasikan pertumbuhan dengan buku KIA atau aplikasi pemantauan tumbuh kembang\n   • Perhatikan tanda-tanda perkembangan motorik dan kognitif sesuai usia\n   • Diskusikan pertumbuhan anak saat kunjungan rutin ke dokter anak\n\nPertahankan pola hidup dan makan sehat ini untuk memastikan ${t} tetap tumbuh optimal dan terhindar dari stunting di masa mendatang.`};return"Stunting Berat"===a&&r&&r.status.includes("Kurang")?g.stuntingBeratWithUnderweight():"Stunting Berat"===a?g.stuntingBerat():"Stunting Ringan"===a&&r&&r.status.includes("Kurang")?g.stuntingRinganWithUnderweight():"Stunting Ringan"===a?g.stuntingRingan():g.normal()}getMinNormalHeight(a,n){if("undefined"!=typeof stuntingReference){const i=parseInt(a),e="Laki-laki"===n?0:1;if(stuntingReference[i])return stuntingReference[i][e]}let i="Laki-laki"===n?50:49;return i+=a<=12?1.5*a:18+.7*(a-12),parseFloat(i.toFixed(1))}getIdealWeight(a,n){return a<=12?parseFloat((("Laki-laki"===n?3.5:3.3)+.5*a).toFixed(1)):parseFloat((8+a/12*2).toFixed(1))}}let n;document.addEventListener("DOMContentLoaded",(function(){n=new a}))}}]);